"""v122: the tutorial that shows instead of tells (Faz 1): spotlight lines, flight labels, Hezarfen's one-sentence
lessons, the guide office's and the agency's screens."""
from s1_ui import add

# The spotlight's one line (Hezarfen's small face beside it)
add("tut.price", "Lower the price: more passengers board.", "Fiyatı düşür: daha çok yolcu biner.", "Senk den Preis: Mehr Passagiere steigen ein.", "Baja el precio: subirán más pasajeros.", "料金を下げよ。乗客が増えるぞ。", "가격을 내리게. 승객이 더 탄다네.")
add("tut.priceSeen", "See? More passengers. Now tap Done.", "Gördün mü? Yolcu arttı. Tamam'a bas.", "Siehst du? Mehr Passagiere. Jetzt tippe auf Fertig.", "¿Ves? Más pasajeros. Ahora toca Listo.", "見たか？乗客が増えた。OKを押せ。", "봤나? 승객이 늘었지. 이제 완료를 누르게.")
add("tut.go", "You're ready: collect passengers and fly.", "Hazırsın: yolcu topla ve uç.", "Du bist bereit: Passagiere einsammeln und los.", "Estás listo: reúne pasajeros y vuela.", "準備はできた。乗客を集めて飛べ。", "준비됐네. 승객을 모으고 날게.")
add("tut.burn", "Hold it: you climb.", "Basılı tut: yükselirsin.", "Gedrückt halten: Du steigst.", "Mantén pulsado: subes.", "押し続けよ。上昇するぞ。", "꾹 누르고 있게. 올라간다네.")
add("tut.wind", "To go forward, find the right height.", "İleri gitmek için doğru yüksekliği bul.", "Um voranzukommen, finde die richtige Höhe.", "Para avanzar, busca la altura adecuada.", "前へ進むには、ちょうどよい高さを探せ。", "앞으로 가려면 알맞은 높이를 찾게.")
add("tut.vent", "The vent lets the hot air out: you sink, it doesn't take you forward.", "Valf sıcak havayı bırakır: alçalırsın, ileri götürmez.", "Das Ventil lässt die heiße Luft ab: Du sinkst, vorwärts bringt es dich nicht.", "La válvula suelta el aire caliente: bajas, pero no avanzas.", "ベントは熱い空気を逃がす。高度は下がるが、前へは進まん。", "밸브는 뜨거운 공기를 빼낸다네. 내려갈 뿐, 앞으로 가진 않지.")
add("tut.field", "Land here.", "Burada in.", "Hier landen.", "Aterriza aquí.", "ここに降りよ。", "여기에 내리게.")
add("tut.chimney", "Pass over the fairy chimney: if the basket hits it, that's a crash.", "Peribacasının üstünden geç: sepet çarparsa kaza.", "Flieg über den Feenkamin: Stößt der Korb dagegen, ist das ein Unfall.", "Pasa por encima de la chimenea de hadas: si la cesta choca, es un accidente.", "妖精の煙突の上を越えよ。バスケットがぶつかれば事故だ。", "요정의 굴뚝 위로 넘어가게. 바스켓이 부딪히면 사고라네.")
add("tut.thermal", "A thermal: fly into it and it carries you up.", "Termik: içine girersen seni yukarı taşır.", "Eine Thermik: Flieg hinein, dann trägt sie dich nach oben.", "Una térmica: entra en ella y te subirá.", "上昇気流だ。中に入れば上へ運んでくれる。", "상승기류라네. 안으로 들어가면 위로 올려 주지.")
add("tut.skip", "Skip", "Geç", "Überspringen", "Saltar", "スキップ", "건너뛰기")
add("tut.more", "More", "Daha fazla", "Mehr", "Más", "もっと読む", "더 보기")
add("tut.poor", "Not enough cash yet: once it's there, you do it here.", "Kasan şimdilik yetmiyor: para birikince buradan yaparsın.", "Die Kasse reicht noch nicht: Sobald das Geld da ist, machst du es hier.", "Aún no tienes suficiente dinero: cuando lo tengas, lo haces aquí.", "まだ資金が足りない。貯まったら、ここで行うのだ。", "아직 돈이 모자라네. 돈이 모이면 여기서 하게.")
add("tut.poorHotel", "Your stars or your cash aren't enough for this hotel yet: once you've grown, you sign here.", "Bu otel için yıldızın ya da kasan yetmiyor: büyüyünce buradan anlaşırsın.", "Für dieses Hotel reichen deine Sterne oder deine Kasse noch nicht: Wenn du gewachsen bist, unterschreibst du hier.", "Para este hotel aún no te bastan las estrellas o el dinero: cuando crezcas, firmas aquí.", "このホテルには星か資金がまだ足りない。成長したら、ここで提携するのだ。", "이 호텔과 제휴하기엔 별이나 돈이 아직 모자라네. 커지면 여기서 계약하게.")
add("tut.a11y", "Hezarfen's tip", "Hezarfen'in ipucu", "Hezarfens Tipp", "Consejo de Hezarfen", "ヘザルフェンのヒント", "헤자르펜의 조언")

# Drawn in the flight scene
add("flight.chimneyLabel", "If the basket hits: crash", "Sepet çarparsa kaza", "Korb stößt an: Unfall", "Si la cesta choca: accidente", "バスケットが当たれば事故", "바스켓이 닿으면 사고")
add("flight.thermalTag", "Thermal ↑", "Termik ↑", "Thermik ↑", "Térmica ↑", "上昇気流 ↑", "상승기류 ↑")
add("flight.thermalColumn", "THERMAL ↑", "TERMİK ↑", "THERMIK ↑", "TÉRMICA ↑", "上昇気流 ↑", "상승기류 ↑")
add("flight.toTarget", "TO TARGET", "HEDEFE", "ZUM ZIEL", "AL OBJETIVO", "目標へ", "목표로")

# The passenger estimate counting up when the price goes down
add("price.paxUp", "Passengers: +%@", "+%@ yolcu", "Passagiere: +%@", "Pasajeros: +%@", "+%@人", "+%@명")

# Hezarfen's lessons of the first days in one sentence; the long text stays behind "More"
add("tip.welcome.short", "Welcome, kid! Just one job today: set your price, collect passengers, fly.", "Hoş geldin evlat! Bugün tek işin var: fiyatı belirle, yolcu topla, uç.", "Willkommen, Lehrling! Heute nur eine Aufgabe: Preis festlegen, Passagiere einsammeln, fliegen.", "¡Bienvenido, aprendiz! Hoy solo tienes una tarea: fija el precio, reúne pasajeros y vuela.", "よく来たな、弟子よ！今日の仕事はひとつ。料金を決め、乗客を集め、飛ぶのだ。", "어서 오게, 제자여! 오늘 할 일은 하나뿐일세. 가격을 정하고, 승객을 모으고, 날게.")
add("tip.insurance.short", "You switch insurance on and off here now, kid; one accident can empty your cash in a single morning.", "Sigortayı artık buradan açıp kapatırsın evlat; bir kaza kasayı bir sabahta boşaltabilir.", "Die Versicherung schaltest du jetzt hier an und aus, Lehrling; ein Unfall kann deine Kasse an einem Morgen leeren.", "Ahora activas y desactivas el seguro aquí, aprendiz; un accidente puede vaciar tu caja en una sola mañana.", "これからは保険をここで切り替えるのだ、弟子よ。一度の事故で一朝にして金庫が空になるぞ。", "이제 보험은 여기서 켜고 끄게, 제자여. 사고 한 번이면 하루아침에 금고가 빌 수 있다네.")
add("tip.fleet.short", "The hangar is open, kid: once the cash is there, you buy your second balloon here.", "Hangar açıldı evlat: kasa dolunca ikinci balonu buradan alırsın.", "Der Hangar ist offen, Lehrling: Sobald die Kasse reicht, kaufst du hier deinen zweiten Ballon.", "El hangar está abierto, aprendiz: cuando tengas el dinero, aquí compras tu segundo globo.", "格納庫が開いたぞ、弟子よ。金が貯まったら、ここで二機目の気球を買うのだ。", "격납고가 열렸네, 제자여. 돈이 모이면 여기서 두 번째 열기구를 사게.")
add("tip.bank.short", "The bank is open: a loan speeds you up, but interest is a patient enemy, kid.", "Banka açıldı: kredi hızlandırır ama faiz sabırlı bir düşmandır evlat.", "Die Bank ist offen: Ein Kredit macht dich schneller, aber Zinsen sind ein geduldiger Feind, Lehrling.", "El banco está abierto: un préstamo te acelera, pero el interés es un enemigo paciente, aprendiz.", "銀行が開いた。借金は勢いをくれるが、利子は辛抱強い敵だぞ、弟子よ。", "은행이 열렸네. 대출은 속도를 내 주지만 이자는 끈질긴 적이라네, 제자여.")
add("tip.crew.short", "The pilot office is open: every balloon needs a pilot, kid.", "Pilot ofisi açıldı: her balona bir pilot lazım evlat.", "Das Pilotenbüro ist offen: Jeder Ballon braucht einen Piloten, Lehrling.", "La oficina de pilotos está abierta: cada globo necesita un piloto, aprendiz.", "パイロット事務所が開いた。気球には一機ごとにパイロットが要るぞ、弟子よ。", "조종사 사무실이 열렸네. 열기구마다 조종사가 필요하다네, 제자여.")
add("tip.market.short", "Your sales office is open: sign with hotels and their guests come to you, kid.", "Satış ofisin açıldı: otellerle anlaşırsan misafirleri sana gelir evlat.", "Dein Verkaufsbüro ist offen: Mit Hotelverträgen kommen ihre Gäste zu dir, Lehrling.", "Tu oficina de ventas está abierta: si firmas con hoteles, sus huéspedes vendrán a ti, aprendiz.", "販売所が開いた。ホテルと提携すれば、その客がお前のもとに来るぞ、弟子よ。", "판매 사무실이 열렸네. 호텔과 제휴하면 그 손님들이 자네에게 온다네, 제자여.")
add("tip.guide.short", "The guide office is open: fly a guide and they'll send you tourists, kid.", "Rehber ofisi açıldı: bir rehberi uçur, sana turist göndersin evlat.", "Das Guide-Büro ist offen: Nimm einen Guide mit, dann schickt er dir Touristen, Lehrling.", "La oficina de guías está abierta: lleva a un guía y te mandará turistas, aprendiz.", "ガイド事務所が開いた。ガイドを乗せれば観光客を送ってくれるぞ、弟子よ。", "가이드 사무소가 열렸네. 가이드를 태워 주면 관광객을 보내 준다네, 제자여.")
add("tip.agency.short", "The influencer agency is open: it's pricey, but it lifts your popularity fast.", "Influencer ajansı açıldı: pahalıdır ama popülerliğini hızla yükseltir.", "Die Influencer-Agentur ist offen: teuer, aber sie steigert deine Beliebtheit schnell.", "La agencia de influencers está abierta: es cara, pero sube tu popularidad muy rápido.", "インフルエンサー事務所が開いた。高いが、人気を一気に上げてくれる。", "인플루언서 에이전시가 열렸네. 비싸지만 인기를 빠르게 올려 준다네.")
add("tip.bazaar.short", "The bazaar is open, kid: I've left you a set of lanterns as a gift, go and take it.", "Çarşı açıldı evlat: sana bir fener seti hediye ettim, al bakalım.", "Der Basar ist offen, Lehrling: Ich habe dir ein Laternenset geschenkt, hol es dir.", "El bazar está abierto, aprendiz: te he regalado un juego de farolillos, ve a por él.", "バザールが開いたぞ、弟子よ。ランタンのセットを贈っておいた。受け取るがよい。", "바자르가 열렸네, 제자여. 랜턴 세트를 선물로 두었으니 가져가게.")
add("tip.workshop.short", "The balloon workshop's plot is ready: build it and you design your own balloons, kid.", "Balon atölyesinin arsası hazır: kurarsan kendi balonlarını tasarlarsın evlat.", "Das Grundstück der Ballonwerkstatt ist bereit: Bau sie, und du entwirfst deine eigenen Ballone, Lehrling.", "El solar del taller de globos está listo: constrúyelo y diseñarás tus propios globos, aprendiz.", "気球工房の土地が整った。建てれば自分の気球をデザインできるぞ、弟子よ。", "열기구 공방 부지가 준비됐네. 지으면 자네 열기구를 직접 디자인한다네, 제자여.")
add("tip.school.short", "The pilot school's plot is ready: its graduates cost less and crash less.", "Pilot okulunun arsası hazır: mezunları ucuz ve daha az kaza yapar.", "Das Grundstück der Pilotenschule ist bereit: Ihre Absolventen sind günstiger und verunglücken seltener.", "El solar de la escuela de pilotos está listo: sus graduados cobran menos y tienen menos accidentes.", "パイロット学校の土地が整った。卒業生は安く、事故も少ない。", "조종사 학교 부지가 준비됐네. 졸업생은 싸고 사고도 덜 낸다네.")
add("tip.goals.short", "Tap Goals, kid: your chapter goals are there.", "Hedef düğmesine dokun evlat: bölüm hedeflerin orada.", "Tippe auf Ziele, Lehrling: Dort stehen deine Kapitelziele.", "Toca Objetivos, aprendiz: ahí están los objetivos de tu capítulo.", "「目標」を押してみよ、弟子よ。章の目標が書いてある。", "'목표'를 눌러 보게, 제자여. 챕터 목표가 거기 있다네.")
add("tip.price.short", "Yesterday seats stayed empty, kid: lower the price a little and they fill up.", "Dün koltuklar boş kaldı evlat: fiyatı biraz düşürürsen dolar.", "Gestern blieben Plätze leer, Lehrling: Senk den Preis ein wenig, dann füllen sie sich.", "Ayer quedaron plazas vacías, aprendiz: baja un poco el precio y se llenarán.", "昨日は空席が出たな、弟子よ。料金を少し下げれば埋まる。", "어제는 빈 좌석이 남았네, 제자여. 가격을 조금 내리면 찬다네.")
add("tip.yellow.short", "Yellow flag, kid: fly with the pricey insurance or let the balloons rest.", "Sarı bayrak evlat: ya pahalı sigortayla uç ya da balonları dinlendir.", "Gelbe Flagge, Lehrling: Flieg mit der teuren Versicherung oder gönn den Ballonen eine Pause.", "Bandera amarilla, aprendiz: vuela con el seguro caro o deja descansar los globos.", "黄色の旗だ、弟子よ。高い保険で飛ぶか、気球を休ませるかだ。", "노란 깃발이네, 제자여. 비싼 보험을 들고 날든지 열기구를 쉬게 하게.")
add("tip.red.short", "Red flag, kid: staying on the ground today is no shame.", "Kırmızı bayrak evlat: bugün yerde kalmak ayıp değil.", "Rote Flagge, Lehrling: Heute am Boden zu bleiben ist keine Schande.", "Bandera roja, aprendiz: quedarse hoy en tierra no es ninguna vergüenza.", "赤い旗だ、弟子よ。今日は地上に留まっても恥ではない。", "빨간 깃발이네, 제자여. 오늘은 땅에 머물러도 부끄러울 것 없다네.")
add("tip.mission.short", "Your first special customer is here, kid: hold the balloon between 250 and 350 m for 8 seconds, then land gently.", "İlk özel müşterin geldi evlat: balonu 250–350 m arasında 8 saniye tut, sonra yumuşak in.", "Dein erster besonderer Kunde ist da, Lehrling: Halte den Ballon 8 Sekunden zwischen 250 und 350 m, dann lande sanft.", "Ha llegado tu primer cliente especial, aprendiz: mantén el globo entre 250 y 350 m durante 8 segundos y luego aterriza con suavidad.", "初めての特別なお客だ、弟子よ。気球を250〜350 mで8秒保ち、それからそっと降りよ。", "첫 특별 손님이 왔네, 제자여. 열기구를 250~350 m 사이에 8초간 유지하고 살포시 내리게.")
add("tip.accident.short", "An accident is bad but not the end, kid: wait for the repair and win your popularity back.", "Kaza kötü ama son değil evlat: onarımı bekle, popülerliğini topla.", "Ein Unfall ist schlimm, aber nicht das Ende, Lehrling: Warte die Reparatur ab und hol dir deine Beliebtheit zurück.", "Un accidente es malo, pero no es el final, aprendiz: espera la reparación y recupera tu popularidad.", "事故は痛いが終わりではない、弟子よ。修理を待ち、人気を取り戻せ。", "사고는 나쁘지만 끝은 아니라네, 제자여. 수리를 기다리며 인기를 되찾게.")
add("tip.pr.short", "Early on, hotel and guide deals are everything, kid.", "Başlarda otel ve rehber anlaşmaları her şeydir evlat.", "Am Anfang sind Verträge mit Hotels und Guides alles, Lehrling.", "Al principio, los acuerdos con hoteles y guías lo son todo, aprendiz.", "最初はホテルとガイドとの提携がすべてだ、弟子よ。", "처음에는 호텔과 가이드 제휴가 전부라네, 제자여.")
add("tip.rivals.short", "The first secret of sinking a rival is seats: once your seats cover the tourists, the rival flies empty.", "Rakip batırmanın ilk sırrı koltuktur: koltuğun turiste yetince rakip boş uçar.", "Das erste Geheimnis, um Konkurrenten zu versenken, sind Sitzplätze: Reichen deine Plätze für die Touristen, fliegt die Konkurrenz leer.", "El primer secreto para hundir a un rival son las plazas: cuando tus plazas cubren a los turistas, el rival vuela vacío.", "ライバルを沈める第一の秘訣は座席だ。お前の座席で観光客をまかなえれば、ライバルは空席で飛ぶ。", "경쟁자를 무너뜨리는 첫 비결은 좌석이라네. 자네 좌석이 관광객을 감당하면 경쟁사는 빈 채로 날지.")
add("tip.aging.short", "One of your balloons has a tired envelope, kid: renew it on the fleet page.", "Bir balonunun zarfı yorulmuş evlat: Filo sayfasından yenile.", "Die Hülle eines deiner Ballone ist müde, Lehrling: Erneuere sie auf der Flottenseite.", "La envoltura de uno de tus globos está cansada, aprendiz: renuévala desde la página de la flota.", "お前の気球の一機、球皮がくたびれておるぞ、弟子よ。フリート画面で張り替えよ。", "열기구 하나의 외피가 낡았네, 제자여. 기단 페이지에서 교체하게.")

